        address thisAddr = address(this);
        bool callerIsOwner = (thisAddr == before);

        bool reverted;
        c.setOwner(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

